 let law:serde_json::Value=serde_json::from_str(include_str!("../../🎞️command/📥️custody/🛂️manifest/metadata.json")).unwrap();
 for selected in [false,true]{let surface=selected.then_some("selected-original-surface");for cut in [Some(0),Some(1),Some(8),Some(32),Some(128),Some(1024),None]{let mut value=law["view"].clone();value["panelJson"]=serde_json::Value::String("α🙂".repeat(8197));let original=Some(ActionMeta{actor:"fixture original".into(),instance_id:71,view_state:Some(serde_json::from_value(value.clone()).unwrap())});let mut registry=match surface{Some(surface)=>SurfaceContexts::original_surface_read_fixture(surface,original.as_ref().unwrap().view_state.as_ref().unwrap()),None=>SurfaceContexts::original_read_fixture(original.as_ref().unwrap().view_state.as_ref().unwrap())};let view=registry.view().unwrap();let pointers=(view.panel_json.as_ref().unwrap().as_ptr(),view.window_instances.as_ptr(),view.active_utility_by_window_id.original_root_identity(),view.tool_run_trace_cursor_by_window_id.original_root_identity());let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut source=None;let d=RetirementDemand{capacity_bytes:size_of::<OriginalResponseActionSource>(),..header::<OriginalResponseActionSource>()};for denied in [RetainedCloneGrant{maximum_items:0,..TURN},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..TURN},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..TURN},RetainedCloneGrant{maximum_depth:d.depth-1,..TURN}]{assert!(!event(&mut caller,&mut decoder,denied,|cx|OriginalResponseActionSource::admit_selection(71,surface,cx,&mut source)));assert!(source.is_none());assert_eq!(caller.receipt(),Default::default());}event(&mut caller,&mut decoder,TURN,|cx|OriginalResponseActionSource::admit_selection(71,surface,cx,&mut source));if let Some(surface)=surface{let foreign_surface=surface.to_owned();event(&mut caller,&mut decoder,TURN,|cx|{assert!(source.as_mut().unwrap().advance_cache(Some(&foreign_surface),&mut registry,cx).is_err());Ok(())});}let actor="original actor α🙂".repeat(31);let mut foreign=OriginalJobDecodeOwner::empty();event(&mut caller,&mut foreign,TURN,|cx|{assert!(source.as_mut().unwrap().advance_cache(surface,&mut registry,cx).is_err());Ok(())});
 for index in 0..262144{if cut==Some(index){caller.cancel().cancel_now();break}let source=source.as_mut().unwrap();let ready=event(&mut caller,&mut decoder,TURN,|cx|if source.phase<2{source.advance_cache(surface,&mut registry,cx).map(|_|false)}else{source.advance_actor(&actor,cx)});if ready{break}assert!(index<262143)}
 if cut.is_none(){let meta=source.as_ref().unwrap().metadata.as_ref().unwrap();assert_eq!(meta.actor.as_str(),actor);assert_eq!(serde_json::to_value(meta.view_state.as_ref().unwrap()).unwrap(),value);assert_eq!(meta.view_state.as_ref().unwrap().active_utility_by_window_id.original_root_identity(),pointers.2);assert_eq!(meta.view_state.as_ref().unwrap().tool_run_trace_cursor_by_window_id.original_root_identity(),pointers.3);}
 for index in 0..262144{if source.as_ref().unwrap().terminal_is_empty(){break}let d=source.as_ref().unwrap().close_demands(&registry).unwrap();for axis in 0..5{let mut denied=TURN;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}event(&mut caller,&mut decoder,denied,|cx|cx.with_original_retirement(|cx|{let source=source.as_mut().unwrap();if let Some(capture)=source.capture.as_mut(){if !capture.terminal_is_empty(){capture.close_step(&mut registry,cx)?;return Ok(false)}close_original_retained_step(cx,d,|_|{source.capture.take();Ok(RetainedCloneStep::Progress(progress(d)))})?;return Ok(false)}source.close_owned(cx)}));assert_eq!(caller.receipt(),Default::default());assert_eq!(source.as_ref().unwrap().close_demands(&registry).unwrap(),d);}event(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|{let source=source.as_mut().unwrap();if let Some(capture)=source.capture.as_mut(){if !capture.terminal_is_empty(){capture.close_step(&mut registry,cx)?;return Ok(false)}let d=OriginalSurfaceViewCapture::release_demand();close_original_retained_step(cx,d,|_|{source.capture.take();Ok(RetainedCloneStep::Progress(progress(d)))})?;return Ok(false)}source.close_owned(cx)}));assert!(index<262143)}
 let view=registry.view().unwrap();assert_eq!((view.panel_json.as_ref().unwrap().as_ptr(),view.window_instances.as_ptr(),view.active_utility_by_window_id.original_root_identity(),view.tool_run_trace_cursor_by_window_id.original_root_identity()),pointers);event(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=OriginalResponseActionSource::release_demand();close_original_retained_step(cx,d,|_|{source.take();Ok(RetainedCloneStep::Progress(progress(d)))})?;Ok(())}));while !registry.original_terminal_is_empty(){event(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|registry.close_original_step(cx)));}
 let mut original=original;let mut close=RetainedCloneClose::default();for index in 0..262144{if original.is_none()&&close.is_empty(){break}event(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=close.next_owner_demands::<ActionMeta>(original.is_some(),&None,32768)?;close_original_retained_step(cx,d,|g|if let Some(step)=close.begin_granted(&mut original,g)?{Ok(step)}else{close.select(32768)?.step(g)})?;Ok(())}));assert!(index<262143)}for decoder in [&mut decoder,&mut foreign]{while !decoder.terminal_is_empty(){caller.turn(TURN,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(32768)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}}caller.retire(TURN);
 }}
